import{_ as s,C as a,o as e,c as d,a2 as l,b as g,w as n,a as o,E as i,a3 as A}from"./chunks/framework.BBdhqAg0.js";const E="data:image/png;base64,iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAQAAAC1HAwCAAAAC0lEQVR42mNkYAAAAAYAAjCB0C8AAAAASUVORK5CYII=",b=JSON.parse('{"title":"부지 정보 관리","description":"","frontmatter":{},"headers":[],"relativePath":"project/site-manage.md","filePath":"project/site-manage.md","lastUpdated":1793113754000}'),x={name:"project/site-manage.md"};function c(y,t,B,C,f,h){const r=a("Mermaid");return e(),d("div",null,[t[1]||(t[1]=l('<h1 id="부지-정보-관리" tabindex="-1">부지 정보 관리 <a class="header-anchor" href="#부지-정보-관리" aria-label="Permalink to &quot;부지 정보 관리&quot;">​</a></h1><div class="tip custom-block"><p class="custom-block-title">📸 실제 화면 안내</p><p><img src="'+E+'" alt="사업 부지 지번 및 매입 계약 관리 화면"><em>관리자 참고: 해당 화면의 실제 캡처 이미지를 <code>./images/site-manage.png</code> 경로에 등록해 주세요.</em></p></div><blockquote><p><strong>부지 정보 관리</strong>는 부동산 개발 프로젝트의 핵심 기초 자산인 사업 부지의 필지별 물리적 정보, 소유자별 지분 현황 및 토지 매매 계약 체결·대금 지급 현황을 통합적으로 관리하는 모듈입니다.</p></blockquote><ul><li><strong>접근 경로</strong>: 시스템 좌측 내비게이션 메뉴에서 **[PJT 관리 시스템] → [프로젝트 설정] → [부지 정보 관리]**를 선택하여 접속합니다.</li></ul>',4)),(e(),g(A,null,{default:n(()=>[i(r,{id:"mermaid-20",class:"mermaid",graph:"flowchart%20LR%0A%20%20%20%20A%5B%221.%20%EC%A7%80%EB%B2%88%20%EB%AA%A9%EB%A1%9D%20%EB%93%B1%EB%A1%9D%3Cbr%3E(%ED%95%84%EC%A7%80%20%EB%A9%B4%EC%A0%81%C2%B7%EC%A7%80%EB%AA%A9%C2%B7%EB%93%B1%EA%B8%B0%EB%B6%80%EB%93%B1%EB%B3%B8)%22%5D%20--%3E%20B%5B%222.%20%EC%86%8C%EC%9C%A0%EC%9E%90%EB%B3%84%20%EC%A7%80%EB%B6%84%20%EC%97%B0%EA%B2%B0%3Cbr%3E(%EC%9D%B8%EC%A0%81%EC%82%AC%ED%95%AD%C2%B7%EC%A7%80%EB%B6%84%EC%9C%A8%C2%B7%ED%86%A0%EC%A7%80%EC%82%AC%EC%9A%A9%EB%8F%99%EC%9D%98)%22%5D%0A%20%20%20%20B%20--%3E%20C%5B%223.%20%EB%A7%A4%EC%9E%85%20%EA%B3%84%EC%95%BD%20%EC%B2%B4%EA%B2%B0%3Cbr%3E(%EB%A7%A4%EB%A7%A4%EB%8C%80%EA%B8%88%C2%B7%EA%B3%84%EC%95%BD%2F%EC%9E%94%EA%B8%88%20%EC%A7%80%EA%B8%89%20%EC%9D%BC%EC%A0%95)%22%5D%0A%20%20%20%20C%20--%3E%20D%5B%22%F0%9F%93%8A%20%EC%86%8C%EC%9C%A0%EA%B6%8C%20%ED%99%95%EB%B3%B4%EC%9C%A8%20%26%3Cbr%3E%ED%86%A0%EC%A7%80%EB%8C%80%20%EC%A7%91%ED%96%89%20%EB%AA%A8%EB%8B%88%ED%84%B0%EB%A7%81%22%5D%0A"})]),fallback:n(()=>[...t[0]||(t[0]=[o(" Loading... ",-1)])]),_:1})),t[2]||(t[2]=l('<h2 id="_1-지번-목록-관리" tabindex="-1">1. 지번 목록 관리 <a class="header-anchor" href="#_1-지번-목록-관리" aria-label="Permalink to &quot;1. 지번 목록 관리&quot;">​</a></h2><p>사업 부지를 구성하는 개별 필지(지번)의 물리적 정보와 공적 장부상 권리 관계를 등록합니다.</p><ul><li><strong>위치</strong>: <code>프로젝트 설정 &gt; 부지 정보 관리 &gt; 지번 목록 관리</code></li><li><strong>엑셀 다운로드 지원</strong>: 등록된 전체 지번 목록을 엑셀 파일로 추출할 수 있습니다. (권리제한사항 포함 여부 선택 가능)</li></ul><table tabindex="0"><thead><tr><th style="text-align:left;">라벨</th><th style="text-align:center;">필수입력</th><th style="text-align:left;">상세 설명 및 실무 기준</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>행정동 / 지번</strong></td><td style="text-align:center;"><strong>필수</strong></td><td style="text-align:left;">필지의 행정 구역 및 세부 본번-부번 (예: <code>OO동 123-45</code>)</td></tr><tr><td style="text-align:left;"><strong>지목</strong></td><td style="text-align:center;"><strong>필수</strong></td><td style="text-align:left;">대지, 전, 답, 임야, 도로 등 토지의 실제/공부상 지목</td></tr><tr><td style="text-align:left;"><strong>공부상 면적</strong></td><td style="text-align:center;"><strong>필수</strong></td><td style="text-align:left;">토지대장상 기재된 공식 면적 (제곱미터, ㎡)</td></tr><tr><td style="text-align:left;"><strong>환지 면적</strong></td><td style="text-align:center;"></td><td style="text-align:left;">환지 방식 도시개발사업인 경우 실제 권리 배정 면적 (㎡)</td></tr><tr><td style="text-align:left;"><strong>권리 제한 사항</strong></td><td style="text-align:center;"></td><td style="text-align:left;">갑구(소유권 가등기, 가압류 등), 을구(근저당권, 지상권 등) 제한 사항 기록</td></tr><tr><td style="text-align:left;"><strong>등기부 등본</strong></td><td style="text-align:center;"></td><td style="text-align:left;">해당 필지의 최신 등기사항전부증명서(등기부등본) PDF 첨부</td></tr></tbody></table><h2 id="_2-소유자-별-관리" tabindex="-1">2. 소유자 별 관리 <a class="header-anchor" href="#_2-소유자-별-관리" aria-label="Permalink to &quot;2. 소유자 별 관리&quot;">​</a></h2><p>부지 소유자의 인적 사항과 소유 지분, 토지 사용 동의 여부를 관리합니다.</p><ul><li><strong>위치</strong>: <code>프로젝트 설정 &gt; 부지 정보 관리 &gt; 소유자 별 관리</code></li><li><strong>엑셀 다운로드 지원</strong>: 소유자별 지분 현황 및 비상 연락처 목록을 엑셀 파일로 다운로드할 수 있습니다.</li></ul><table tabindex="0"><thead><tr><th style="text-align:left;">라벨</th><th style="text-align:center;">필수입력</th><th style="text-align:left;">상세 설명 및 실무 기준</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>소유구분</strong></td><td style="text-align:center;"><strong>필수</strong></td><td style="text-align:left;">개인, 법인, 국공유지(기획재정부, 국토부, 지자체 등) 중 선택</td></tr><tr><td style="text-align:left;"><strong>소유자 / 식별정보</strong></td><td style="text-align:center;"><strong>필수</strong></td><td style="text-align:left;">소유자 성명(또는 법인명) 및 생년월일/사업자번호</td></tr><tr><td style="text-align:left;"><strong>연락처 / 주소</strong></td><td style="text-align:center;"></td><td style="text-align:left;">주/보조 연락처 및 실거주지 우편번호 기반 주소 입력</td></tr><tr><td style="text-align:left;"><strong>소유부지</strong></td><td style="text-align:center;"><strong>필수</strong></td><td style="text-align:left;">해당 소유자가 지분을 보유한 필지 선택 (공동 소유 시 다중 선택 가능)</td></tr><tr><td style="text-align:left;"><strong>소유지분 / 면적</strong></td><td style="text-align:center;"><strong>필수</strong></td><td style="text-align:left;">필지별 소유 지분율(%) 및 실제 지분 환산 면적 (㎡)</td></tr><tr><td style="text-align:left;"><strong>사용동의</strong></td><td style="text-align:center;"></td><td style="text-align:left;">인허가 신청을 위한 <strong>토지 사용 승낙서 징구 여부</strong> 설정</td></tr></tbody></table><h2 id="_3-매입-계약-관리" tabindex="-1">3. 매입 계약 관리 <a class="header-anchor" href="#_3-매입-계약-관리" aria-label="Permalink to &quot;3. 매입 계약 관리&quot;">​</a></h2><p>소유자별 부지 매매 계약 조건과 대금 지급(계약금, 중도금, 잔금) 일정을 관리합니다.</p><ul><li><strong>위치</strong>: <code>프로젝트 설정 &gt; 부지 정보 관리 &gt; 매입 계약 관리</code></li><li><strong>엑셀 다운로드 지원</strong>: 부지 매입 계약 현황 및 대금 지급 데이터를 엑셀 파일로 추출하여 사업비 집행 보고서 등에 활용할 수 있습니다.</li></ul><table tabindex="0"><thead><tr><th style="text-align:left;">라벨</th><th style="text-align:center;">필수입력</th><th style="text-align:left;">상세 설명 및 실무 기준</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>소유자</strong></td><td style="text-align:center;"><strong>필수</strong></td><td style="text-align:left;">매입 대상 소유자 선택</td></tr><tr><td style="text-align:left;"><strong>총 매매가격</strong></td><td style="text-align:center;"><strong>필수</strong></td><td style="text-align:left;">부동산 매매 계약서상의 총 매매 금액 (원)</td></tr><tr><td style="text-align:left;"><strong>총 계약면적</strong></td><td style="text-align:center;"><strong>필수</strong></td><td style="text-align:left;">해당 계약으로 확보되는 토지 면적 (제곱미터, ㎡)</td></tr><tr><td style="text-align:left;"><strong>계약 체결일</strong></td><td style="text-align:center;"><strong>필수</strong></td><td style="text-align:left;">매매 계약서상의 공식 계약 체결 일자</td></tr><tr><td style="text-align:left;"><strong>대금 지급 정보</strong></td><td style="text-align:center;"><strong>필수</strong></td><td style="text-align:left;">계약금(1·2차), 중도금, 잔금별 금액, 지급 약정일, 지급 완료 여부 관리</td></tr><tr><td style="text-align:left;"><strong>입금 계좌</strong></td><td style="text-align:center;"><strong>필수</strong></td><td style="text-align:left;">토지대 입금을 위한 은행, 계좌번호, 예금주 정보</td></tr><tr><td style="text-align:left;"><strong>소유권 확보</strong></td><td style="text-align:center;"></td><td style="text-align:left;">잔금 지급 및 소유권 이전 등기 완료 여부 설정</td></tr><tr><td style="text-align:left;"><strong>계약서 파일</strong></td><td style="text-align:center;"></td><td style="text-align:left;">날인 완료된 부동산 매매 계약서 스캔본(PDF) 첨부</td></tr></tbody></table><h2 id="_4-신입사원을-위한-실무-가이드" tabindex="-1">4. 신입사원을 위한 실무 가이드 <a class="header-anchor" href="#_4-신입사원을-위한-실무-가이드" aria-label="Permalink to &quot;4. 신입사원을 위한 실무 가이드&quot;">​</a></h2><ul><li><strong>💡 부지 정보 관리 3단계 표준 워크플로우</strong>: <ol><li><code>[지번 목록 관리]</code>에서 사업 구역 내 모든 필지를 등록합니다.</li><li><code>[소유자 별 관리]</code>에서 지주 정보를 등록하고 해당 필지와 지분율을 연결합니다.</li><li><code>[매입 계약 관리]</code>에서 매매 계약을 체결하고 회차별 대금 지급 일정을 관리합니다.</li></ol></li><li><strong>💡 토지 사용 승낙서 징구율의 중요성</strong>: <ul><li>주택건설사업계획승인 등 인허가를 접수하기 위해서는 일정 비율 이상의 토지 사용 동의(사용한 권원 확보)가 필수적입니다. 소유자별 관리에서 <strong>&#39;사용동의&#39;</strong> 체크를 철저히 관리하여 사업 추진 요건 충족 여부를 실시간으로 모니터링하십시오.</li></ul></li></ul>',14))])}const m=s(x,[["render",c]]);export{b as __pageData,m as default};
